/* Field phase weights adapted from Azgaar Battle Simulator (MIT).
   https://github.com/Azgaar/Fantasy-Map-Generator/wiki/Battle-Simulator
   This is an adaptation, not the complete Azgaar combat engine. */
const Military=(()=>{
const types={infantry:{name:'Infantry',icon:'🛡',money:20,metal:8,cloth:4,power:1},archers:{name:'Archers',icon:'🏹',money:25,metal:5,cloth:6,power:1.1},cavalry:{name:'Cavalry',icon:'🐎',money:35,metal:12,cloth:8,power:1.4},artillery:{name:'Artillery crews',icon:'💣',money:45,metal:20,cloth:5,power:1.6}};
const phases={skirmish:{infantry:.2,archers:2.4,cavalry:.1,artillery:3},melee:{infantry:2,archers:1.2,cavalry:1.5,artillery:.5}};
function check(ok,msg){if(!ok)throw Error(msg);}
function units(r){if(!r.units)r.units={infantry:r.troops,archers:0,cavalry:0,artillery:0};return r.units;}
function sync(r){r.troops=Object.values(r.units).reduce((a,b)=>a+b,0);}
function upgrade(s){s.release='0.4.0';s.regiments.forEach(r=>{units(r);r.supplyStatus=r.supplyStatus||'Not checked yet';});return s;}
function recruit(s,id,type='infantry'){check(s.phase==='implement','Recruit during Implement.');const r=s.regiments.find(r=>r.id===id),t=types[type];check(r&&t,'Choose a regiment and troop type.');const c=s.countries[r.country],cell=s.cells[r.cell];check(cell.country===c.id,'Recruit in your own territory.');check(cell.population>=30&&c.stock.metal>=t.metal&&c.stock.cloth>=t.cloth&&c.stock.money>=t.money&&c.militaryBudget>=t.money,`Need 30 residents, ${t.metal} metal, ${t.cloth} cloth, ${t.money} money and military allowance.`);units(r)[type]+=10;sync(r);cell.population-=10;c.stock.metal-=t.metal;c.stock.cloth-=t.cloth;c.stock.money-=t.money;c.militaryBudget-=t.money;}
function split(s,id){check(s.phase==='implement','Reorganize during Implement.');const r=s.regiments.find(r=>r.id===id);check(r&&r.troops>=20,'Need at least 20 troops to split.');const next={...r,id:s.nextId++,name:s.countries[r.country].name+' Detachment '+s.nextId,units:{},order:null};const old=r.troops;for(const k of Object.keys(types)){const n=Math.floor(units(r)[k]/2);next.units[k]=n;r.units[k]-=n;}sync(r);sync(next);next.supply=r.supply*(next.troops/old);r.supply-=next.supply;s.regiments.push(next);}
function transfer(s,from,to,type,amount){check(s.phase==='implement','Transfer during Implement.');const a=s.regiments.find(r=>r.id===from),b=s.regiments.find(r=>r.id===to);check(a&&b&&a!==b&&a.country===b.country&&a.cell===b.cell,'Regiments must belong to your country and share a cell.');check(types[type]&&Number.isInteger(amount)&&amount>0&&units(a)[type]>=amount,'Choose a valid available troop count.');units(a)[type]-=amount;units(b)[type]+=amount;sync(a);sync(b);}
function connected(s,r,relation){const friendly=id=>id===r.country||relation(s,r.country,id)==='ally',blocked=new Set(s.regiments.filter(x=>x.troops>0&&relation(s,r.country,x.country)==='enemy').map(x=>x.cell)),queue=[[r.cell,0]],seen=new Set([r.cell]);for(let i=0;i<queue.length;i++){const [id,d]=queue[i],c=s.cells[id];if(blocked.has(id)||!friendly(c.country))continue;if(c.country===r.country&&(c.buildings.includes('city')||c.buildings.includes('village')||c.buildings.includes('depot')))return true;if(d>=8)continue;for(const n of c.neighbors)if(s.cells[n].land&&!seen.has(n)){seen.add(n);queue.push([n,d+1]);}}return false;}
function supply(s,c,notes,relation){for(const r of s.regiments.filter(r=>r.country===c.id&&r.troops>0)){const linked=connected(s,r,relation),need=Math.ceil(r.troops*.1),capacity=Math.max(10,r.troops*.8);let take=0;if(linked){take=Math.min(Math.max(0,capacity-r.supply),need*2,c.stock.food);c.stock.food-=take;r.supply+=take;}const shortage=r.supply<need;r.supply=Math.max(0,r.supply-need);r.readiness=Math.max(20,Math.min(100,r.readiness+(shortage?-15:3)));r.supplyStatus=linked?(shortage?'Connected, but food is short':'Connected to a settlement'):(shortage?'Cut off and hungry':'Using carried food');if(shortage)notes.push(`${r.name}: food shortage reduced readiness by 15.`);}}
function resolve(s,notes,relation){const living=s.regiments.filter(r=>r.troops>0).sort((a,b)=>a.id-b.id),meet=(a,b)=>a.cell===b.cell||(a.previousCell===b.cell&&b.previousCell===a.cell),wants=(a,b)=>relation(s,a.country,b.country)!=='ally'&&(a.stance==='all'||a.stance==='target'&&a.target===b.country);const fled=new Set();for(const r of living){if(r.stance!=='avoid'||!living.some(e=>e.country!==r.country&&meet(r,e)&&wants(e,r)))continue;const safe=s.cells[r.cell].neighbors.find(id=>s.cells[id].land&&s.cells[id].country===r.country&&!living.some(e=>e.country!==r.country&&e.cell===id));if(safe!==undefined){r.cell=safe;r.order=null;fled.add(r.id);notes.push(`${r.name} withdrew to cell ${safe}.`);}}
const targets=new Map(living.map(r=>[r.id,new Set()]));for(let i=0;i<living.length;i++)for(let j=i+1;j<living.length;j++){const a=living[i],b=living[j];if(fled.has(a.id)||fled.has(b.id)||a.country===b.country||!meet(a,b)||relation(s,a.country,b.country)==='ally'||!wants(a,b)&&!wants(b,a))continue;targets.get(a.id).add(b.id);targets.get(b.id).add(a.id);s.relations[[a.country,b.country].sort((x,y)=>x-y).join('-')]='enemy';}
const damage=new Map(living.map(r=>[r.id,0])),losses=new Map(living.map(r=>[r.id,0]));for(const phase of ['skirmish','melee']){damage.forEach((v,k)=>damage.set(k,0));for(const a of living){const enemies=[...targets.get(a.id)].map(id=>living.find(r=>r.id===id)).filter(r=>r.troops>0);if(!a.troops||!enemies.length)continue;const power=Object.entries(units(a)).reduce((n,[k,count])=>n+count*types[k].power*phases[phase][k],0)*(a.readiness/100)*(1+.1*s.countries[a.country].tech.arms);for(const b of enemies){const cell=s.cells[b.cell],defense=(cell.country===b.country?1.15:1)*(cell.elevation>.65?1.2:1)*(cell.buildings.includes('fort')?1.35:1);damage.set(b.id,damage.get(b.id)+power*.09/enemies.length/defense);}}
for(const r of living){const loss=Math.min(r.troops,Math.round(damage.get(r.id)));if(!loss)continue;const before=r.troops,allocation=Object.keys(types).map(k=>({k,exact:units(r)[k]/before*loss}));allocation.forEach(a=>a.n=Math.floor(a.exact));let left=loss-allocation.reduce((n,a)=>n+a.n,0);allocation.sort((a,b)=>b.exact-b.n-(a.exact-a.n)||a.k.localeCompare(b.k));for(const a of allocation)if(left>0&&a.n<r.units[a.k]){a.n++;left--;}allocation.forEach(a=>r.units[a.k]-=a.n);sync(r);losses.set(r.id,losses.get(r.id)+loss);}}
const swapped=new Set();for(const a of living)for(const b of living)if(a.id!==b.id&&targets.get(a.id).has(b.id)&&a.previousCell===b.cell&&b.previousCell===a.cell&&a.cell!==b.cell){swapped.add(a.id);swapped.add(b.id);}for(const r of living){if(!targets.get(r.id).size)continue;r.readiness=Math.max(20,r.readiness-10);r.order=null;if(swapped.has(r.id))r.cell=r.previousCell;notes.push(`Battle: ${r.name} lost ${losses.get(r.id)}; ${r.troops} troops remain after skirmish and melee.`);}}
function validate(s){for(const r of s.regiments)check(Object.keys(types).every(k=>Number.isInteger(units(r)[k])&&r.units[k]>=0)&&Object.values(r.units).reduce((a,b)=>a+b,0)===r.troops,'Troop composition does not match regiment total.');}
return {types,phases,upgrade,recruit,split,transfer,connected,supply,resolve,validate};})();
